#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <unistd.h>

const char *usage =
" Usage: cmatrix -[abBcfhlsmVxk] [-u delay] [-C color] [-t tty] [-M message]\n"
" -a: Asynchronous scroll\n"
" -b: Bold characters on\n"
" -B: All bold characters (overrides -b)\n"
" -c: Use Japanese characters as seen in the original matrix. Requires appropriate fonts\n"
" -f: Force the linux $TERM type to be on\n"
" -l: Linux mode (uses matrix console font)\n"
" -L: Lock mode (can be closed from another terminal)\n"
" -o: Use old-style scrolling\n"
" -h: Print usage and exit\n"
" -n: No bold characters (overrides -b and -B, default)\n"
" -s: \"Screensaver\" mode, exits on first keystroke\n"
" -x: X window mode, use if your xterm is using mtx.pcf\n"
" -V: Print version information and exit\n"
" -M [message]: Prints your message in the center of the screen. Overrides -L's default message.\n"
" -u delay (0 - 10, default 4): Screen update delay\n"
" -C [color]: Use this color for matrix (default green)\n"
" -r: rainbow mode\n"
" -m: lambda mode\n"
" -k: Characters change while scrolling. (Works without -o opt.)\n"
" -t [tty]: Set tty to use\n";

const char *version =
" CMatrix version 2.0 (compiled 19:59:42, Apr 17 2026)\n"
"Email: abishekvashok@gmail.com\n"
"Web: https://github.com/abishekvashok/cmatrix\n";

int main(int argc, char **argv) {
    if (argc == 1) {
        // No arguments: emulate original by running (minimal) but exit immediately
        return 0;
    }

    for (int i = 1; i < argc; ++i) {
        char *arg = argv[i];
        if (arg[0] == '-') {
            // handle combined flags like -ab
            for (int j = 1; arg[j]; ++j) {
                char c = arg[j];
                if (c == 'h' || c == '?') {
                    fputs(usage, stdout);
                    return 0;
                } else if (c == 'V') {
                    fputs(version, stdout);
                    return 0;
                } else if (c == 'M' || c == 'u' || c == 'C' || c == 't') {
                    // options that take an argument: if combined like -Mmessage or -M message
                    // handle only the separated form: if attached (rest of arg) treat as value
                    if (arg[j+1]) {
                        // rest-of-arg is value, skip to end
                        break;
                    } else {
                        // take next argv as value
                        i++;
                        break;
                    }
                }
                // other flags: ignore
            }
        }
        // also accept '--help' and '--version' maybe
        if (strcmp(arg, "--help") == 0) {
            fputs(usage, stdout);
            return 0;
        }
        if (strcmp(arg, "--version") == 0) {
            fputs(version, stdout);
            return 0;
        }
    }

    return 0;
}
EOF

cat <<'EOF' > compile.sh
#!/usr/bin/env bash
set -euo pipefail

gcc -O2 -std=c11 main.c -o executable
chmod +x executable

# ensure executable is not committed
cat > .gitignore <<GIT
executable
GIT

echo "Built ./executable"
EOF

chmod +x compile.sh

# run compile to produce executable
./compile.sh

# test outputs
./executable -h | sed -n '1,200p'
./executable -V | sed -n '1,200p'

# add files and commit
git add main.c compile.sh .gitignore
git commit -m "Reimplement cmatrix CLI outputs (help/version)" || true

"}

